**`web/src/components/Settings/AccessTokenSection.tsx`** — listAccessTokens(function), AccessTokenSection(function)

```tsx
1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import copy from "copy-to-clipboard";
3	import { PlusIcon, TrashIcon } from "lucide-react";
4	import { useEffect, useState } from "react";
5	import { toast } from "react-hot-toast";
6	import ConfirmDialog from "@/components/ConfirmDialog";
7	import { Button } from "@/components/ui/button";
8	import { userServiceClient } from "@/connect";
9	import useCurrentUser from "@/hooks/useCurrentUser";
10	import { useDialog } from "@/hooks/useDialog";
11	import { handleError } from "@/lib/error";
12	import { CreatePersonalAccessTokenResponse, PersonalAccessToken } from "@/types/proto/api/v1/user_service_pb";
13	import { useTranslate } from "@/utils/i18n";
14	import CreateAccessTokenDialog from "../CreateAccessTokenDialog";
15	import SettingGroup from "./SettingGroup";
16	import SettingTable from "./SettingTable";
17	
18	const listAccessTokens = async (parent: string) => {
19	  const { personalAccessTokens } = await userServiceClient.listPersonalAccessTokens({ parent });
20	  return personalAccessTokens.sort(
21	    (a, b) =>
22	      ((b.createdAt ? timestampDate(b.createdAt) : undefined)?.getTime() ?? 0) -
23	      ((a.createdAt ? timestampDate(a.createdAt) : undefined)?.getTime() ?? 0),
24	  );
25	};
26	
27	const AccessTokenSection = () => {
28	  const t = useTranslate();
29	  const currentUser = useCurrentUser();
30	  const [personalAccessTokens, setPersonalAccessTokens] = useState<PersonalAccessToken[]>([]);
31	  const createTokenDialog = useDialog();
32	  const [deleteTarget, setDeleteTarget] = useState<PersonalAccessToken | undefined>(undefined);
33	
34	  useEffect(() => {
35	    if (!currentUser?.name) return;
36	    let canceled = false;
37	    listAccessTokens(currentUser.name)
38	      .then((tokens) => {
39	        if (!canceled) {
40	          setPersonalAccessTokens(tokens);
41	        }
42	      })
43	      .catch((error: unknown) => {
44	        if (!canceled) {
45	          handleError(error, toast.error, { context: "List access tokens" });
46	        }
47	      });
48	    return () => {
49	      canceled = true;
50	    };
51	  }, [currentUser?.name]);
52	
53	  const handleCreateAccessTokenDialogConfirm = async (response: CreatePersonalAccessTokenResponse) => {
54	    const tokens = await listAccessTokens(currentUser?.name ?? "");
55	    setPersonalAccessTokens(tokens);
56	    // Copy the token to clipboard - this is the only time it will be shown
57	    if (response.token) {
58	      copy(response.token);
59	      toast.success(t("setting.access-token.access-token-copied-to-clipboard"));
60	    }
61	    toast.success(
62	      t("setting.access-token.create-dialog.access-token-created", {
63	        description: response.personalAccessToken?.description ?? "",
64	      }),
65	    );
66	  };
67	
68	  const handleDeleteAccessToken = (token: PersonalAccessToken) => {
69	    setDeleteTarget(token);
70	  };
71	
72	  const confirmDeleteAccessToken = async () => {
73	    if (!deleteTarget) return;
74	    const { name: tokenName, description } = deleteTarget;
75	    await userServiceClient.deletePersonalAccessToken({ name: tokenName });
76	    setPersonalAccessTokens((prev) => prev.filter((token) => token.name !== tokenName));
77	    setDeleteTarget(undefined);
78	    toast.success(t("setting.access-token.access-token-deleted", { description }));
79	  };
80	
81	  return (
82	    <SettingGroup
83	      title={t("setting.access-token.title")}
84	      description={t("setting.access-token.description")}
85	      actions={
86	        <Button onClick={createTokenDialog.open} size="sm">
87	          <PlusIcon className="w-4 h-4 mr-1.5" />
88	          {t("common.create")}
89	        </Button>
90	      }
91	    >
92	      <SettingTable
93	        columns={[
94	          {
95	            key: "description",
96	            header: t("common.description"),
97	            render: (_, token: PersonalAccessToken) => <span className="text-foreground">{token.description}</span>,
98	          },
99	          {
100	            key: "createdAt",
101	            header: t("setting.access-token.create-dialog.created-at"),
102	            render: (_, token: PersonalAccessToken) => (token.createdAt ? timestampDate(token.createdAt) : undefined)?.toLocaleString(),
103	          },
104	          {
105	            key: "expiresAt",
106	            header: t("setting.access-token.create-dialog.expires-at"),
107	            render: (_, token: PersonalAccessToken) =>
108	              (token.expiresAt ? timestampDate(token.expiresAt) : undefined)?.toLocaleString() ??
109	              t("setting.access-token.create-dialog.duration-never"),
110	          },
111	          {
112	            key: "actions",
113	            header: "",
114	            className: "text-right",
115	            render: (_, token: PersonalAccessToken) => (
116	              <Button variant="ghost" size="sm" onClick={() => handleDeleteAccessToken(token)}>
117	                <TrashIcon className="text-destructive w-4 h-auto" />
118	              </Button>
119	            ),
120	          },
121	        ]}
122	        data={personalAccessTokens}
123	        emptyMessage={t("setting.access-token.no-tokens-found")}
124	        getRowKey={(token) => token.name}
125	      />
126	
127	      {/* Create Access Token Dialog */}
128	      <CreateAccessTokenDialog
129	        open={createTokenDialog.isOpen}
130	        onOpenChange={createTokenDialog.setOpen}
131	        onSuccess={handleCreateAccessTokenDialogConfirm}
132	      />
133	      <ConfirmDialog
134	        open={!!deleteTarget}
135	        onOpenChange={(open) => !open && setDeleteTarget(undefined)}
136	        title={deleteTarget ? t("setting.access-token.access-token-deletion", { description: deleteTarget.description }) : ""}
137	        description={t("setting.access-token.access-token-deletion-description")}
138	        confirmLabel={t("common.delete")}
139	        cancelLabel={t("common.cancel")}
140	        onConfirm={confirmDeleteAccessToken}
141	        confirmVariant="destructive"
142	      />
143	    </SettingGroup>
144	  );
145	};
146	
147	export default AccessTokenSection;
```

